type ModelCatalogAction =
	| { type: "loading" }
	| { type: "ready"; models: SelectableModel[]; webGpuAvailable: boolean }
	| { type: "error"; message: string; fallbackModels: SelectableModel[]; webGpuAvailable: boolean };

