	switch (action.type) {
		case "loading":
			return { ...state, status: "loading", error: "" };
		case "ready":
			return { models: action.models, status: "ready", error: "", webGpuAvailable: action.webGpuAvailable };
		case "error":
			return {
				models: action.fallbackModels,
				status: "error",
				error: action.message,
