						const pct = Math.round(progress.progress ?? 0);
						this.state = { ...this.state, loadingProgress: pct };
						this.notify();
					}
				},
			});

			if (!this.isCurrentLoad(epoch)) return;

			this.state = {
				loaded: true,
				loading: false,
				loadingProgress: 100,
				error: null,
				modelId: spec.id,
				model,
				processor,
				tokenizer,
			};
			this.notify();
			console.log(`[local-model] ${spec.id} ready`);
